export function OpenGraphImage({
  title = "{{title}}",
  domain = "{{domain}}",
  theme = "{{theme}}",
  ratio = "{{ratio}}",
}) {
  const dark = theme === "dark";
  return (
    <div style={{ maxWidth: 360, borderRadius: 10, overflow: "hidden", border: "1px solid #24143022",
      font: "13px/1.4 system-ui, sans-serif", background: dark ? "#241430" : "#FAF7F2", color: dark ? "#FAF7F2" : "#241430" }}>
      <div style={{ display: "block", width: "100%", aspectRatio: ratio }} aria-hidden="true">
        <svg viewBox="0 0 400 210" width="100%" height="100%" preserveAspectRatio="xMidYMid slice">
          <rect width="400" height="210" fill="#F5C2E0" />
          <circle cx="320" cy="50" r="26" fill="#E8A020" />
          <path d="M0 170 L100 110 L200 160 L300 90 L400 150 L400 210 L0 210 Z" fill="#BFD9F2" />
        </svg>
      </div>
      <div style={{ padding: "10px 12px" }}>
        <p style={{ margin: "0 0 4px", fontWeight: 600 }}>{title}</p>
        <p style={{ margin: 0, opacity: 0.6, textTransform: "uppercase", fontSize: 11, letterSpacing: "0.04em" }}>{domain}</p>
      </div>
    </div>
  );
}
